--- a/src/lib/OpenEXR/ImfIDManifest.cpp
+++ b/src/lib/OpenEXR/ImfIDManifest.cpp
@@ -470,6 +470,20 @@ IDManifest::init (const char* data, const char* endOfData)
     }
 #endif

+    //
+    // the RLE table is not required to cover every string in the table;
+    // entries it leaves out stay zeroed. Check the decoded mapping before
+    // it is used to resolve component names below.
+    //
+    for (size_t i = 0; i < stringList.size (); ++i)
+    {
+        if (mapping[i] < 0 || mapping[i] >= int (stringList.size ()))
+        {
+            throw IEX_NAMESPACE::InputExc (
+                "Corrupt mapping table in IDManifest");
+        }
+    }
+
     //
     // number of manifest entries comes after string list
